def somme_liste(nombres):
    total = 0
    for n in nombres:
        total += n
    return total

def trouver_maximum(nombres):
    plus_grand = nombres[0]
    for n in nombres:
        if n > plus_grand:
            plus_grand = n
    return plus_grand

def compter_occurrences(liste, valeur):
    compteur = 0
    for element in liste:
        if element == valeur:
            compteur += 1
    return compteur

def liste_des_carres(nombres):
    resultat = []
    for n in nombres:
        resultat.append(n * n)
    return resultat

def compter_mots_par_longueur(texte):
    mots = texte.split()
    result = {}
    for mot in mots:
        longueur = len(mot)
        result[longueur] = result.get(longueur, 0) + 1
    return result

class CompteBancaire:
    def __init__(self, solde=0):
        self.solde = solde

    def deposer(self, montant):
        if montant <= 0:
            return False
        self.solde += montant
        return True

    def retirer(self, montant):
        if montant <= 0 or montant > self.solde:
            return False
        self.solde -= montant
        return True

class Panier:
    def __init__(self):
        self.articles = {}

    def ajouter(self, nom, prix, quantite=1):
        if quantite <= 0 or prix < 0:
            return False
        if nom in self.articles:
            self.articles[nom]["quantite"] += quantite
        else:
            self.articles[nom] = {"prix": prix, "quantite": quantite}
        return True

    def retirer(self, nom):
        return self.articles.pop(nom, None) is not None

    def total(self):
        somme = 0
        for article in self.articles.values():
            somme += article["prix"] * article["quantite"]
        return somme

class CompteurBorne:
    def __init__(self, minimum=0, maximum=10):
        self.minimum = minimum
        self.maximum = maximum
        self.valeur = minimum

    def incrementer(self, pas=1):
        self.valeur = min(self.valeur + pas, self.maximum)
        return self.valeur

    def decrementer(self, pas=1):
        self.valeur = max(self.valeur - pas, self.minimum)
        return self.valeur

    def reinitialiser(self):
        self.valeur = self.minimum

class Pile:
    def __init__(self, capacite=3):
        self.capacite = capacite
        self.elements = []

    def empiler(self, element):
        if len(self.elements) >= self.capacite:
            return False
        self.elements.append(element)
        return True

    def depiler(self):
        if not self.elements:
            return None
        return self.elements.pop()

    def sommet(self):
        if not self.elements:
            return None
        return self.elements[-1]

    def taille(self):
        return len(self.elements)

class Vehicule:
    def __init__(self, marque):
        self.marque = marque
        self.kilometrage = 0

    def rouler(self, km):
        if km <= 0:
            return False
        self.kilometrage += km
        return True


class VehiculeElectrique(Vehicule):
    def __init__(self, marque, batterie=100):
        super().__init__(marque)
        self.batterie = batterie

    def rouler(self, km):
        if km > self.batterie:
            return False
        if not super().rouler(km):
            return False
        self.batterie -= km
        return True

    def recharger(self):
        self.batterie = 100

class Employe:
    def __init__(self, nom, salaire_base):
        self.nom = nom
        self.salaire_base = salaire_base

    def salaire(self):
        return self.salaire_base

    def augmenter(self, pourcentage):
        if pourcentage <= 0:
            return False
        self.salaire_base = self.salaire_base * (100 + pourcentage) // 100
        return True


class Manager(Employe):
    def __init__(self, nom, salaire_base, prime=100):
        super().__init__(nom, salaire_base)
        self.prime = prime
        self.equipe = []

    def ajouter_membre(self, nom):
        if nom in self.equipe:
            return False
        self.equipe.append(nom)
        return True

    def salaire(self):
        return super().salaire() + self.prime * len(self.equipe)

class Playlist:
    def __init__(self, nom="Ma playlist"):
        self.nom = nom
        self.titres = []

    def ajouter(self, titre):
        if titre in self.titres:
            return False
        self.titres.append(titre)
        return True

    def retirer(self, titre):
        if titre not in self.titres:
            return False
        self.titres.remove(titre)
        return True

    def __len__(self):
        return len(self.titres)

    def __contains__(self, titre):
        return titre in self.titres

    def __str__(self):
        return f"{self.nom} ({len(self)} titre(s))"

    def __repr__(self):
        return f"Playlist({self.nom!r}, {self.titres!r})"

class Inventaire:
    def __init__(self):
        self.stock = {}

    def ajouter(self, nom, quantite=1):
        if quantite <= 0:
            return False
        self.stock[nom] = self.stock.get(nom, 0) + quantite
        return True

    def retirer(self, nom, quantite=1):
        if quantite <= 0 or self.stock.get(nom, 0) < quantite:
            return False
        self.stock[nom] -= quantite
        if self.stock[nom] == 0:
            del self.stock[nom]
        return True

    def __len__(self):
        return len(self.stock)

    def __contains__(self, nom):
        return nom in self.stock

    def __str__(self):
        parties = []
        for nom in sorted(self.stock):
            parties.append(f"{nom}:{self.stock[nom]}")
        return ", ".join(parties)
